    long long k;
    cin >> n >> k;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    unordered_map<long long, long long> count;
    count[0] = 1;
    long long prefix = 0, total = 0;
    for (int i = 0; i < n; i++) {
        prefix ^= a[i];
        auto it = count.find(prefix ^ k);
        if (it != count.end()) total += it->second;
        count[prefix]++;
    }
    cout << total << "\n";

    return 0;
